SELECT CAST([], 'Array(Tuple(String, String))') AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT grid.timestamp AS timestamp, if(ifNull(scalar_values.sample_count, 0) = 1, scalar_values.any_value, nan) AS value FROM (SELECT arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({start_ms:Int64}, ({end_ms:Int64} + {step_ms:Int64}), {step_ms:Int64}))) AS timestamp) AS grid LEFT JOIN (SELECT point.1 AS timestamp, count() AS sample_count, any(point.2) AS any_value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, argMax(d.value, d.timestamp) AS value FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({scalar_child_start_ms:Int64}, {scalar_child_end_ms:Int64} + {scalar_child_step_ms:Int64}, {scalar_child_step_ms:Int64}))) AS eval_ts FROM (
            SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {scalar_child_range_instant_matcher_0_value:String} AND src.tags[concat('', {scalar_child_range_instant_matcher_1_key:String})] = {scalar_child_range_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({scalar_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({scalar_child_required_end_ms:Int64})
        ) AS series) AS grid INNER JOIN timeSeriesData(`observability`.`prometheus`) AS d ON d.id = grid.id WHERE d.timestamp >= fromUnixTimestamp64Milli({scalar_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({scalar_child_required_end_ms:Int64}) AND d.timestamp <= grid.eval_ts - toIntervalMillisecond({scalar_child_offset_ms:Int64}) AND d.timestamp >= grid.eval_ts - toIntervalMillisecond({scalar_child_offset_ms:Int64} + {scalar_child_lookback_ms:Int64}) GROUP BY grid.id, grid.tags, grid.eval_ts HAVING NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) AS scalar_child ARRAY JOIN scalar_child.time_series AS point GROUP BY point.1) AS scalar_values ON scalar_values.timestamp = grid.timestamp ORDER BY timestamp)
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
